const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// --- Background ---

Given('the app is loaded in the browser', function () {
  this.loadApp();
});

// --- Empty state ---

Given('the todo list is empty', function () {
  this.window.localStorage.clear();
  this.reloadApp();
  assert.strictEqual(this.todoItems.length, 0, 'Expected todo list to be empty');
});

Then('the main section is hidden', function () {
  const main = this.mainSection;
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', 'Expected main section to be hidden');
});

Then('the footer is hidden', function () {
  const footer = this.footer;
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'Expected footer to be hidden');
});

// --- Creating todos ---

When('the user types {string} in the new-todo input and presses Enter', function (text) {
  this.typeInNewTodo(text);
  this.pressEnterInNewTodo();
});

Then('the todo list contains {int} item(s)', function (count) {
  assert.strictEqual(this.todoItems.length, count, `Expected ${count} items but found ${this.todoItems.length}`);
});

Then('the new-todo input is empty', function () {
  assert.strictEqual(this.newTodoInput.value, '', 'Expected new-todo input to be empty');
});

Then('the todo at index {int} has title {string} and is not completed', function (index, title) {
  const item = this.todoItemAt(index);
  assert.ok(item, `No todo at index ${index}`);
  const label = item.querySelector('label');
  assert.strictEqual(label.textContent, title, `Expected title "${title}" but got "${label.textContent}"`);
  assert.ok(!item.classList.contains('completed'), 'Expected todo to not be completed');
});

Then('the todo list is empty', function () {
  assert.strictEqual(this.todoItems.length, 0, 'Expected todo list to be empty');
});

// --- Single todo existence ---

Given('a todo {string} exists', function (title) {
  this.createTodo(title, false);
});

Given('a completed todo {string} exists', function (title) {
  this.createTodo(title, true);
});

// --- Multiple todos existence ---

Given('these todos exist:', function (dataTable) {
  this.createTodosWithData(dataTable);
});

// --- Completing todos ---

When('the user toggles the checkbox for todo {string}', function (title) {
  this.toggleTodoByTitle(title);
});

Then('the todo {string} is completed', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(item.classList.contains('completed'), `Expected "${title}" to be completed`);
});

Then('the todo {string} is not completed', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(!item.classList.contains('completed'), `Expected "${title}" to not be completed`);
});

Then('the item count shows {string}', function (expected) {
  const countEl = this.todoCount;
  assert.ok(countEl, 'Todo count element not found');
  const strong = countEl.querySelector('strong');
  const countText = strong.textContent;
  const suffix = countEl.textContent.replace(countText, '').trim();
  const actual = `${countText} ${suffix}`;
  assert.strictEqual(actual, expected, `Expected "${expected}" but got "${actual}"`);
});

// --- Toggle all ---

When('the user toggles the toggle-all checkbox on', function () {
  this.toggleAllOn();
});

Then('all todos are completed', function () {
  this.todoItems.forEach((item, i) => {
    assert.ok(item.classList.contains('completed'), `Todo at index ${i} not completed`);
  });
});

Then('the toggle-all checkbox is unchecked', function () {
  assert.ok(!this.toggleAllCheckbox.checked, 'Expected toggle-all to be unchecked');
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(this.toggleAllCheckbox.checked, 'Expected toggle-all to be checked');
});

// --- Editing ---

When('the user double-clicks the label for todo {string}', function (title) {
  this.doubleClickLabel(title);
});

Then('the todo {string} is in editing mode', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(item.classList.contains('editing'), `Expected "${title}" to be in editing mode`);
});

When('the user clears the edit input and types {string} and presses Enter', function (text) {
  this.clearEditAndType(text);
  this.pressEnterInEdit();
});

When('the user clears the edit input and types {string} and triggers blur', function (text) {
  this.clearEditAndType(text);
  this.blurEdit();
});

When('the user clears the edit input and presses Enter', function () {
  this.clearEditAndType('');
  this.pressEnterInEdit();
});

When('the user clears the edit input and types {string} and presses Escape', function (text) {
  this.clearEditAndType(text);
  this.pressEscapeInEdit();
});

Then('the todo {string} is not in editing mode', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(!item.classList.contains('editing'), `Expected "${title}" to not be in editing mode`);
});

// --- Deleting ---

When('the user clicks the destroy button for todo {string}', function (title) {
  this.clickDestroyForTodo(title);
});

// --- Counter ---

Then('the item count shows {int} item(s) left', function (count) {
  const countEl = this.todoCount;
  assert.ok(countEl, 'Todo count element not found');
  const strong = countEl.querySelector('strong');
  assert.strictEqual(parseInt(strong.textContent, 10), count, `Expected count ${count}`);
  const fullText = countEl.textContent.trim();
  if (count === 1) {
    assert.ok(fullText.includes('1 item left'), `Expected "1 item left" but got "${fullText}"`);
  } else {
    assert.ok(fullText.includes(`${count} items left`), `Expected "${count} items left" but got "${fullText}"`);
  }
});

// --- Clear completed ---

When('the user clicks the Clear completed button', function () {
  this.clickClearCompleted();
});

Then('the Clear completed button is hidden', function () {
  const style = this.window.getComputedStyle(this.clearCompletedButton);
  assert.strictEqual(style.display, 'none', 'Expected Clear completed button to be hidden');
});

Then('the Clear completed button is visible', function () {
  const style = this.window.getComputedStyle(this.clearCompletedButton);
  assert.notStrictEqual(style.display, 'none', 'Expected Clear completed button to be visible');
});

// --- Persistence ---

When('the page is reloaded', function () {
  this.reloadApp();
});

// --- Routing ---

When('the user navigates to the {string} filter', function (filter) {
  this.navigateToFilter(filter);
});

Then('the visible todo list contains {int} item(s)', function (count) {
  const visibleItems = this.todoItems.filter(li => {
    const style = this.window.getComputedStyle(li);
    return style.display !== 'none';
  });
  assert.strictEqual(visibleItems.length, count, `Expected ${count} visible items but found ${visibleItems.length}`);
});

Then('the visible todo at index {int} has title {string}', function (index, title) {
  const visibleItems = this.todoItems.filter(li => {
    const style = this.window.getComputedStyle(li);
    return style.display !== 'none';
  });
  const item = visibleItems[index];
  assert.ok(item, `No visible todo at index ${index}`);
  const label = item.querySelector('label');
  assert.strictEqual(label.textContent, title, `Expected title "${title}" but got "${label.textContent}"`);
});

Then('the {string} filter is selected', function (filter) {
  const selected = this.getSelectedFilter();
  assert.strictEqual(selected, filter, `Expected "${filter}" filter to be selected but got "${selected}"`);
});

