/**
 * TodoMVC App - Vanilla JavaScript implementation
 * @planks("the app is loaded in the browser")
 */
(function () {
  'use strict';

  // --- Storage ---
  var STORAGE_KEY = 'todos-shakedown';

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // --- State ---
  var todos = loadTodos();
  var currentFilter = getFilterFromHash();

  function getFilterFromHash() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  // --- DOM refs ---
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  // --- Render ---
  function render() {
    var filtered = todos.filter(function (todo) {
      if (currentFilter === 'active') return !todo.completed;
      if (currentFilter === 'completed') return todo.completed;
      return true;
    });

    // Clear list
    todoList.innerHTML = '';

    // Build items
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.setAttribute('data-id', todo.id);
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    // Main section visibility
    var hasTodos = todos.length > 0;
    mainSection.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Toggle all state
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAllCheckbox.checked = allCompleted;

    // Counter
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var pluralized = activeCount === 1 ? 'item left' : 'items left';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralized;

    // Clear completed visibility
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? 'block' : 'none';

    // Filter selection
    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
    });
    var filterHash = currentFilter === 'active' ? '#/active' : currentFilter === 'completed' ? '#/completed' : '#/';
    filterLinks.forEach(function (link) {
      if (link.getAttribute('href') === filterHash) {
        link.classList.add('selected');
      }
    });
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  // --- Helpers ---
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
  }

  function findTodoById(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return todos[i];
    }
    return null;
  }

  function findTodoIndexById(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return i;
    }
    return -1;
  }

  // --- Event handlers ---

  // New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      addTodo();
    }
  });

  function addTodo() {
    var title = newTodoInput.value.trim();
    if (!title) {
      newTodoInput.value = '';
      return;
    }
    todos.push({ id: generateId(), title: title, completed: false });
    saveTodos(todos);
    newTodoInput.value = '';
    render();
  }

  // Toggle all
  toggleAllCheckbox.addEventListener('change', function () {
    var checked = toggleAllCheckbox.checked;
    todos.forEach(function (todo) {
      todo.completed = checked;
    });
    saveTodos(todos);
    render();
  });

  // Todo list events (delegated)
  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      var todo = findTodoById(id);
      if (todo) {
        todo.completed = e.target.checked;
        saveTodos(todos);
        render();
      }
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    if (e.target.tagName === 'LABEL') {
      var li = e.target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.value = e.target.textContent;
      editInput.focus();
    }
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      if (e.key === 'Enter' || e.keyCode === 13) {
        saveEdit(li, id, e.target.value);
      } else if (e.key === 'Escape' || e.keyCode === 27) {
        li.classList.remove('editing');
        e.target.value = findTodoById(id).title;
      }
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      saveEdit(li, id, e.target.value);
    }
  }, true);

  function saveEdit(li, id, value) {
    var trimmed = value.trim();
    if (!trimmed) {
      // Delete todo if edit is empty
      todos = todos.filter(function (t) { return t.id !== id; });
    } else {
      var todo = findTodoById(id);
      if (todo) todo.title = trimmed;
    }
    li.classList.remove('editing');
    saveTodos(todos);
    render();
  }

  todoList.addEventListener('click', function (e) {
    if (e.target.classList.contains('destroy')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      todos = todos.filter(function (t) { return t.id !== id; });
      saveTodos(todos);
      render();
    }
  });

  // Clear completed
  clearCompletedBtn.addEventListener('click', function () {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  });

  // Routing
  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    render();
  });

  filterLinks.forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      window.location.hash = link.getAttribute('href');
    });
  });

  // --- Initial render ---
  render();
})();

