  // Re-run app script to pick up restored localStorage
  const appScriptPath = require('path').resolve(__dirname, '../../js/app.js');
  if (require('fs').existsSync(appScriptPath)) {
    const appScript = require('fs').readFileSync(appScriptPath, 'utf8');
    try {
      this.window.eval(appScript);
    } catch (e) {
      console.error('Error re-running app.js:', e.message);
    }
  }
}

