Then('the item count shows {int} item(s) left', function (count) {
  const countEl = this.todoCount;
  assert.ok(countEl, 'Todo count element not found');
  const strong = countEl.querySelector('strong');
  assert.strictEqual(parseInt(strong.textContent, 10), count, `Expected count ${count}`);
  const fullText = countEl.textContent.trim();
  if (count === 1) {
    assert.ok(fullText.includes('1 item left'), `Expected "1 item left" but got "${fullText}"`);
  } else {
